void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  vec2 uv = fragCoord / iResolution.xy;
  vec2 centered = (uv - 0.5) * vec2(iResolution.x / iResolution.y, 1.0);
  vec2 majorGrid = abs(fract(centered * 10.0) - 0.5);
  float line = 1.0 - smoothstep(0.46, 0.49, max(majorGrid.x, majorGrid.y));
  vec3 quadrants = vec3(step(0.0, centered.x), step(0.0, centered.y), 1.0 - step(0.0, centered.x));
  float circle = 1.0 - smoothstep(0.245, 0.255, abs(length(centered) - 0.25));
  float clock = 0.5 + 0.5 * sin(iTime * uParam_speed);
  vec3 color = mix(quadrants * 0.35, vec3(0.12), line);
  color = mix(color, vec3(clock, 1.0 - clock, 0.5), circle);
  fragColor = vec4(color, uParam_alpha);
}
